import { NuxPopoverData } from './types';
import { Component, ComponentInterface, Event, EventEmitter, h, Host, Prop, Element } from '@stencil/core';
import classNames from 'classnames';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { sendActionTracking, sendDurationTracking, sendExposeTracking } from '@src/shared/unclassified/tracking';
import { Placement, Strategy } from '@floating-ui/dom';
import { PopoverPropTrigger, PopoverSize } from '../ks-popover/types';
import { PopupLength } from '../ks-tooltip';
// import { Slot, Slots } from '@src/framework/decorators';
import { CSSProperties } from '@src/shared/dom';
import { KsIconLoading } from '@fe-infra/keystone-icons-stencil';

const prefix = 'ks-nux-popover';

/**
 * @slot default - The trigger or anchor content that reveals the NUX popover when users interact with it.
 * @slot content - Custom content rendered inside the popover body. Use this slot for richer markup than the `dataSource.content` text.
 */
@Component({
  tag: 'ks-nux-popover',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsNuxPopover implements ComponentInterface {
  @Element() el!: HTMLKsNuxPopoverElement;
  /** The data object containing the content to be displayed within the NUX popover (e.g., title, text, image, buttons). */
  @Prop() dataSource!: NuxPopoverData;
  /** Specifies the layout orientation of the content (e.g., image and text) within the NUX popover. */
  @Prop() orientation: 'vertical' | 'horizontal' = 'vertical';
  // TODO Whether to prevent interaction with elements behind the popover when it is visible.
  // @Prop() preventInteraction = false;
  // TODO Whether the tooltip is visible when the reference element is hidden.
  // @Prop() appendToBody = false;

  /** Controls the visibility of the popup. When `true`, the popup is open. */
  @Prop() open?: boolean;
  /** The default visibility of the popup when the component is first rendered. */
  @Prop() defaultOpen = false;
  /** Controls whether bubbles are disabled. When true, the popup is not open. */
  @Prop() disabled = false;
  /** Fallback text content displayed inside the popup when the `content` slot is not provided. */
  @Prop() content?: string;
  /** The placement of the popup relative to the target element. */
  @Prop() placement: Placement = 'top';
  /** The trigger method for showing the popup. Can be one of the following values: `click`, `hover`, `focus` or `manual`. */
  @Prop() trigger: PopoverPropTrigger = 'click';
  /** Delay before the popup can get open/close, in milliseconds. */
  @Prop() delay?: { open?: number; close?: number };
  /** The background color of the popup. */
  @Prop() color?: string;
  /** The font color of the text inside the popup. */
  @Prop() fontColor?: string;
  /** Indicates whether to inverse the popup. When `true`, the popup will have a highlighted appearance. */
  @Prop() inverse = false;
  /** Controls whether clicking outside the popover closes it. Pass `ignoreEls` to exempt specific elements from outside-click detection. */
  @Prop() closeOnClickOutside: boolean | { ignoreEls: HTMLElement[] } = true;
  /** Indicates whether to display an arrow pointing to the target element. When `true`, the arrow will not be displayed. */
  @Prop() arrow?: boolean = true;
  /** The positioning strategy for the popup. Can be either `"absolute"` or `"fixed"`. */
  @Prop() strategy: Strategy = 'fixed';
  /** The offset between the popup and the target element. */
  @Prop() gapOffset = 0;
  /** The offset for positioning the popup at the start. */
  @Prop() startOffset = 0;
  /** The size of the popup. Can be one of the following values: `"auto"`, `"sm"`, `"md"`, `"lg"`. */
  @Prop() size: PopoverSize = 'md';
  /** The duration of the transition in milliseconds. */
  @Prop() transitionDuration = 200;
  /** The anchor element to which the popup is attached. This can be an element outside the tooltip children. */
  @Prop() anchorEl?: HTMLElement | (() => HTMLElement);
  /** Indicates whether the popup should automatically shift position based on available space. */
  @Prop() autoAdjustments?: { shift?: boolean; flip?: boolean; hideOnAnchorExit?: boolean } = {
    shift: true,
    flip: true,
    hideOnAnchorExit: true,
  };
  /** Overrides the width of the popup decided by `size`. */
  @Prop() popupWidth?: PopupLength | { min?: PopupLength; value?: PopupLength; max?: PopupLength };
  /** Overrides the height of the popup decided by `size`. */
  @Prop() popupHeight?: PopupLength | { min?: PopupLength; value?: PopupLength; max?: PopupLength };
  /** Indicates whether to remove the default padding for the popup content. */
  @Prop() noPadding = false;
  /** The style of the popup content. */
  @Prop() partProps?: { content?: { style?: CSSProperties } };
  /** Overrides the z-index value of the popup. */
  @Prop() zIndex?: string | number;
  /** Triggers after the popup has opened. */
  @Prop() afterOpen?: () => void;
  /** Triggers after the popup has closed. */
  @Prop() afterClose?: () => void;

  /** Custom event that triggers when the visibility of the bubble card changes. */
  @Event({ bubbles: false, composed: false }) ksOpenChange!: EventEmitter<boolean>;

  // @Slot({ slotname: '_default' }) private defaultSlots?: Slots<HTMLSlotElement>;

  constructor() {
    registerPluginManager(this.el);
  }

  render() {
    let defaultPopupWidth: string | undefined;
    if (this.orientation === 'horizontal') {
      defaultPopupWidth = '400px';
    } else {
      defaultPopupWidth = '320px';
    }

    return (
      <Host ks-nux-popover>
        <ks-popover
          open={this.open}
          defaultOpen={this.defaultOpen}
          disabled={this.disabled}
          content={this.content}
          placement={this.placement}
          trigger={this.trigger}
          delay={this.delay}
          color={this.color || 'var(--ks-color-support-fillLow)'}
          fontColor={this.fontColor}
          inverse={this.inverse}
          closeOnClickOutside={this.closeOnClickOutside}
          arrow={this.arrow}
          strategy={this.strategy}
          gapOffset={this.gapOffset}
          startOffset={this.startOffset}
          size={this.size} // size attribute won't break things due to max-width priority but still passed through
          transitionDuration={this.transitionDuration}
          anchorEl={this.anchorEl}
          autoAdjustments={this.autoAdjustments}
          popupWidth={this.popupWidth ?? defaultPopupWidth}
          popupHeight={this.popupHeight}
          noPadding
          partProps={this.partProps}
          zIndex={this.zIndex}
          afterOpen={this.afterOpen}
          afterClose={this.afterClose}
          onKsOpenChange={(event: CustomEvent<boolean>) => {
            if (event.target !== event.currentTarget) {
              return;
            }

            const detail = event.detail;
            if (detail) {
              sendExposeTracking(this.el, { eventType: 'popup' });
              sendDurationTracking(this.el, { eventType: 'popup', reset: true });
            } else {
              sendDurationTracking(this.el, { eventType: 'popup' });
            }
            this.ksOpenChange.emit(detail);
          }}
          data-testid="ks-nux-popover-index-mK9k4r"
        >
          <div
            slot="content"
            class={classNames(`${prefix}`, `${prefix}--${this.orientation}`, this.noPadding && `${prefix}--no-padding`)}
          >
            {this.dataSource.cover && (
              <div class={`${prefix}__img`}>
                <img src={this.dataSource.cover} alt="" />
              </div>
            )}

            <div class={`${prefix}__body`}>
              {this.dataSource.title && (
                <div class={`${prefix}__body--title`}>
                  <ks-text variant="labelLg" color="neutralHigh">
                    {this.dataSource.title}
                  </ks-text>
                </div>
              )}
              <slot name="content">
                {this.dataSource.content && (
                  <div class={`${prefix}__body--content`}>
                    <ks-text variant="labelSm" color="neutralHigh">
                      {this.dataSource.content}
                    </ks-text>
                  </div>
                )}
              </slot>

              {(this.dataSource.actions?.length > 0 || (this.dataSource.total && this.dataSource.current)) && (
                <div class={`${prefix}__body--footer`}>
                  {this.dataSource.total && this.dataSource.current && (
                    <div class="page">
                      <ks-text variant="labelSm" color="neutralHigh">
                        {`${this.dataSource.current} / ${this.dataSource.total}`}
                      </ks-text>
                    </div>
                  )}

                  <div class="buttons">
                    {this.dataSource.actions?.map((button) => (
                      <div
                        onClick={() => {
                          if (button.loading) {
                            return;
                          }
                          button.onClick?.();
                          sendActionTracking(this.el, {
                            eventType: 'click',
                            subEventType: 'button',
                            componentParams: { ...button },
                          });
                        }}
                        class={`button-${button.variant} button`}
                        data-testid="ks-nux-popover-index-aunGbQ"
                      >
                        {button.loading ? <KsIconLoading class={`${prefix}__loading-icon`} size={14} /> : button.label}
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
          <slot></slot>
          {/* /*{!this.appendToBody && <slot></slot>} */}
        </ks-popover>
        {/* {this.appendToBody && <slot></slot>} */}
        {/* {this.preventInteraction && this.innerVisible && <div class={`${prefix}__overlay`} />} */}
      </Host>
    );
  }
}
